{"items":[{"id":"cap-v2-sequence_algorithms-java-repair-01","test_code":"import java.util.Arrays;

public class SolutionTest {
    public static void main(String[] args) {
        assertDoubles(new double[0], Solution.distances(0.0, 0.0, new String[0]), "empty input");

        String[] mixed = {
            "3,4", null, "bad", "6,8", "1,2,3", " ,2", "1, ",
            "NaN,0", "Infinity,0", "-Infinity,0", "1d,2",
            "  -5.0 , 12e0 ", "4.0,-0.0"
        };
        String[] snapshot = mixed.clone();
        assertDoubles(new double[] {5.0, 10.0, 13.0, 4.0},
                Solution.distances(0.0, 0.0, mixed), "skip malformed and retain order");
        assertTrue(Arrays.equals(snapshot, mixed), "input array was modified");

        assertDoubles(new double[] {0.0, 5.0, 5.0e307},
                Solution.distances(1.0, -2.0,
                        new String[] {"1,-2", "4,2", "3e307,4e307"}),
                "center offset and large finite coordinates");

        assertDoubles(new double[] {Double.POSITIVE_INFINITY},
                Solution.distances(-Double.MAX_VALUE, 0.0,
                        new String[] {Double.toString(Double.MAX_VALUE) + ",0"}),
                "overflowing finite-coordinate distance");
    }

    private static void assertDoubles(double[] expected, double[] actual, String label) {
        if (actual == null || expected.length != actual.length) {
            throw new AssertionError(label + ": expected length " + expected.length
                    + " but was " + (actual == null ? "null" : actual.length));
        }
        for (int i = 0; i < expected.length; i++) {
            double e = expected[i];
            double a = actual[i];
            if (Double.isInfinite(e)) {
                if (e != a) {
                    throw new AssertionError(label + " at " + i + ": expected " + e + " but was " + a);
                }
            } else {
                double tolerance = Math.max(1.0e-12, Math.abs(e) * 1.0e-14);
                if (!Double.isFinite(a) || Math.abs(e - a) > tolerance) {
                    throw new AssertionError(label + " at " + i + ": expected " + e + " but was " + a);
                }
            }
        }
    }

    private static void assertTrue(boolean condition, String message) {
        if (!condition) {
            throw new AssertionError(message);
        }
    }
}
"},{"id":"cap-v2-sequence_algorithms-java-repair-02","test_code":"import java.util.Arrays;

public class SolutionTest {
    public static void main(String[] args) {
        byte[] emptyResult1 = Solution.mergeSegments(new byte[0][]);
        byte[] emptyResult2 = Solution.mergeSegments(new byte[0][]);
        assertBytes(new byte[0], emptyResult1, "empty outer array");
        assertTrue(emptyResult1 != emptyResult2, "empty results must be newly allocated");

        byte[] first = {0, 1, -1, Byte.MIN_VALUE, Byte.MAX_VALUE};
        byte[] repeated = {7, 7};
        byte[] empty = new byte[0];
        byte[][] segments = {first, null, empty, repeated, repeated, null, new byte[] {9}};
        byte[][] outerSnapshot = segments.clone();

        byte[] merged = Solution.mergeSegments(segments);
        assertBytes(new byte[] {0, 1, -1, Byte.MIN_VALUE, Byte.MAX_VALUE, 7, 7, 7, 7, 9},
                merged, "null, empty, repeated, and binary segments");
        assertTrue(Arrays.equals(outerSnapshot, segments), "outer input array was modified");
        assertTrue(merged != first && merged != repeated, "result aliases an input segment");

        first[0] = 99;
        repeated[0] = 88;
        segments[6][0] = 77;
        assertBytes(new byte[] {0, 1, -1, Byte.MIN_VALUE, Byte.MAX_VALUE, 7, 7, 7, 7, 9},
                merged, "result changed after input mutation");

        byte[] sole = {4, 5, 6};
        byte[] soleResult = Solution.mergeSegments(new byte[][] {sole});
        assertBytes(sole, soleResult, "single segment");
        assertTrue(soleResult != sole, "single-segment result must be copied");

        byte[][] many = new byte[257][];
        byte[] expectedMany = new byte[256];
        for (int i = 0; i < many.length; i++) {
            if (i == 128) {
                many[i] = null;
            } else {
                many[i] = new byte[] {(byte) i};
                expectedMany[i < 128 ? i : i - 1] = (byte) i;
            }
        }
        assertBytes(expectedMany, Solution.mergeSegments(many), "many ordered segments");
    }

    private static void assertBytes(byte[] expected, byte[] actual, String label) {
        if (!Arrays.equals(expected, actual)) {
            throw new AssertionError(label + ": expected " + Arrays.toString(expected)
                    + " but was " + Arrays.toString(actual));
        }
    }

    private static void assertTrue(boolean condition, String message) {
        if (!condition) {
            throw new AssertionError(message);
        }
    }
}
