Each call to `execute` starts with no workflows and processes valid commands in order:

- `OPEN id` creates an active workflow whose integer value is 0 and emits `id=OPEN`. Reusing an existing id throws `IllegalStateException`.
- `ADD id delta` requires an active workflow, adds the integer delta, records enough history to reverse that addition, and emits `id=value`.
- `ROLLBACK id` requires an active workflow with at least one recorded addition, reverses its most recent addition, and emits `id=value`.
- `COMMIT id` requires an active workflow, permanently commits it, and emits `id=COMMITTED:value`. A committed workflow cannot be changed or committed again.

Workflow state and rollback history must be isolated by id: operations on one id must never change another workflow. Commands follow the exact forms above, with fields separated by one space.

Do not use filesystem access, networking, clocks, randomness, external packages, or frameworks.

Known-bad source:

```java
import java.util.ArrayDeque;
import java.util.ArrayList;
import java.util.Deque;
import java.util.HashMap;
import java.util.List;
import java.util.Map;

public final class Solution {
    private static final class State {
        int value;
        boolean active = true;
        final Deque<Integer> previousValues = new ArrayDeque<Integer>();
    }

    public static List<String> execute(List<String> commands) {
        Map<String, State> states = new HashMap<String, State>();
        List<String> output = new ArrayList<String>();
        State shared = new State();

        for (String command : commands) {
            String[] parts = command.split(" ");
            String operation = parts[0];
            String id = parts[1];

            if (operation.equals("OPEN")) {
                if (states.containsKey(id)) {
                    throw new IllegalStateException("workflow already exists: " + id);
                }
                states.put(id, shared);
                output.add(id + "=OPEN");
                continue;
            }

            State state = states.get(id);
            if (state == null) {
                throw new IllegalStateException("unknown workflow: " + id);
            }
            if (!state.active) {
                throw new IllegalStateException("workflow is committed: " + id);
            }

            if (operation.equals("ADD")) {
                int delta = Integer.parseInt(parts[2]);
                state.previousValues.push(state.value);
                state.value += delta;
                output.add(id + "=" + state.value);
            } else if (operation.equals("ROLLBACK")) {
                if (state.previousValues.isEmpty()) {
                    throw new IllegalStateException("nothing to roll back: " + id);
                }
                state.value = state.previousValues.pop();
                output.add(id + "=" + state.value);
            } else if (operation.equals("COMMIT")) {
                state.active = false;
                state.previousValues.clear();
                output.add(id + "=COMMITTED:" + state.value);
            }
        }
        return output;
    }
}
