   throw new IllegalStateException(\\\"nothing to roll back: \\\" + id);\\n                }\\n                state.value = state.previousValues.pop();\\n                output.add(id + \\\"=\\\" + state.value);\\n            } else if (operation.equals(\\\"COMMIT\\\")) {\\n                state.active = false;\\n                state.previousValues.clear();\\n                output.add(id + \\\"=COMMITTED:\\\" + state.value);\\n            }\\n        }\\n        return output;\\n    }\\n}\\n\",\"known_bad_label\":\"All workflow ids are mapped to one shared State instance, so values, rollback history, and lifecycle transitions leak between workflows.\"},{\"id\":\"cap-v2-string_and_unicode-java-generation-01\",\"problem\":\"Create one complete `Solution.java` file containing a public final class `Solution` and the exact API `public static List<String> registerAndFind(List<String> proposedNames, String query)`.\\n\\nFor every proposed name:\\n\\n1. Normalize it to Unicode NFC.\\n2. Remove leading and trailing code points for which either `Character.isWhitespace` or `Character.isSpaceChar` is true.\\n3. Reject it with `IllegalArgumentException` if the result is empty or contains more than 20 Unicode code points.\\n4. Form its identity key by converting the cleaned name to lowercase with `Locale.ROOT` and normalizing that result to NFC.\\n\\nNames with the same identity key are duplicates. Register only the first such name and preserve its cleaned spelling and input position.\\n\\nClean the query with the same NFC normalization and Unicode-aware trimming, reject a blank query with `IllegalArgumentException`, and form its lowercase identity key in the same way. Return, in registration order, the preserved names whose identity keys contain the query key.\\n\\nDo not use filesystem access, networking, clocks, randomness, external packages, or frameworks.\",\"reference_code\":\"import java.text.Normalizer;\\nimport java.util.ArrayList;\\nimport java.util.HashSet;\\nimport java.util.List;\\nimport java.util.Locale;\\nimport java.util.Set;\\n\\npublic final class Solution {\\n    public static List<String> registerAndFind(List<String> proposedNames, String query) {\\n        List<String> names = new ArrayList<String>();\\n        List<String> keys = new ArrayList<String>();\\n        Set<String> seen = new HashSet<String>();\\n\\n        for (String proposedName : proposedNames) {\\n            String display = clean(proposedName);\\n            if (display.isEmpty() || display.codePointCount(0, display.length()) > 20) {\\n                throw new IllegalArgumentException(\\\"invalid member name\\\");\\n            }\\n            String key = key(display);\\n            if (seen.add(key)) {\\n                names.add(display);\\n                keys.add(key);\\n            }\\n        }\\n\\n        String cleanedQuery = clean(query);\\n        if (cleanedQuery.isEmpty()) {\\n            throw new IllegalArgumentException(\\\"blank query\\\");\\n        }\\n        String queryKey = key(cleanedQuery);\\n        List<String> matches = new ArrayList<String>();\\n        for (int i = 0; i < names.size(); i++) {\\n            if (keys.get(i).contains(queryKey)) {\\n                matches.add(names.get(i));\\n            }\\n        }\\n        return matches;\\n    }\\n\\n    private static String key(String value) {\\n        return Normalizer.normalize(value.toLowerCase(Locale.ROOT), Normalizer.Form.NFC);\\n    }\\n\\n    private static String clean(String value) {\\n        String normalized = Normalizer.normalize(value, Normalizer.Form.NFC);\\n        int start = 0;\\n        int end = normalized.length();\\n        while (start < end) {\\n            int cp = normalized.codePointAt(start);\\n            if (!isUnicodeSpace(cp)) {\\n                break;\\n            }\\n            start += Character.charCount(cp);\\n        }\\n        while (end > start) {\\n            int cp = normalized.codePointBefore(end);\\n            if (!isUnicodeSpace(cp)) {\\n                break;\\n            }\\n            end -= Character.charCount(cp);\\n        }\\n        return normalized.substring(start, end);\\n    }\\n\\n    private static boolean isUnicodeSpace(int codePoint) {\\n        return Character.isWhitespace(codePoint) || Character.isSpaceChar(codePoint);\\n    }\\n}\\n\",\"known_bad_code\":\"import java.text.Normalizer;\\nimport java.util.ArrayList;\\nimport java.util.HashSet;\\nimport java.util.List;\\nimport java.util.Locale;\\nimport java.util.Set;\\n\\npublic final class Solution {\\n    public static List<String> registerAndFind(List<String> proposedNames, String query) {\\n        List<String> names = new ArrayList<String>();\\n        List<String> keys = new ArrayList<String>();\\n        Set<String> seen = new HashSet<String>();\\n\\n        for (String proposedName : proposedNames) {\\n            String display = clean(proposedName);\\n            if (display.isEmpty() || display.codePointCount(0, display.length()) > 20) {\\n                throw new IllegalArgumentException(\\\"invalid member name\\\");\\n            }\\n            String key = key(display);\\n            if (seen.add(display)) {\\n                names.add(display);\\n                keys.add(key);\\n            }\\n        }\\n\\n        String cleanedQuery = clean(query);\\n        if (cleanedQuery.isEmpty()) {\\n            throw new IllegalArgumentException(\\\"blank query\\\");\\n        }\\n        String queryKey = key(cleanedQuery);\\n        List<String> matches = new ArrayList<String>();\\n        for (int i = 0; i < names.size(); i++) {\\n            if (keys.get(i).contains(queryKey)) {\\n                matches.add(names.get(i));\\n            }\\n        }\\n        return matches;\\n    }\\n\\n    private static String key(String value) {\\n        return Normalizer.normalize(value.toLowerCase(Locale.ROOT), Normalizer.Form.NFC);\\n    }\\n\\n    private static String clean(String value) {\\n        String normalized = Normalizer.normalize(value, Normalizer.Form.NFC);\\n        int start = 0;\\n        int end = normalized.length();\\n        while (start < end) {\\n            int cp = normalized.codePointAt(start);\\n            if (!isUnicodeSpace(cp)) {\\n                break;\\n            }\\n            start += Character.charCount(cp);\\n        }\\n        while (end > start) {\\n            int cp = normalized.codePointBefore(end);\\n            if (!isUnicodeSpace(cp)) {\\n                break;\\n            }\\n            end -= Character.charCount(cp);\\n        }\\n        return normalized.substring(start, end);\\n    }\\n\\n    private static boolean isUnicodeSpace(int codePoint) {\\n        return Character.isWhitespace(codePoint) || Character.isSpaceChar(codePoint);\\n    }\\n}\\n\",\"known_bad_label\":\"Duplicate detection uses the preserved display spelling instead of the normalized, case-folded identity key.\"},{\"id\":\"cap-v2-string_and_unicode-java-generation-02\",\"problem\":\"Create one complete `Solution.java` file containing a public final class `Solution` and the exact API `public static List<String> uniqueSlices(String text, int sliceLength)`.\\n\\nBuild a canonical text value by performing these operations in order:\\n\\n1. Normalize `text` to Unicode NFC.\\n2. Remove every code point for which either `Character.isWhitespace` or `Character.isSpaceChar` is true, including whitespace inside the text.\\n3. Convert the result to lowercase using `Locale.ROOT`.\\n4. Normalize the result to NFC again.\\n\\n`sliceLength` is measured in Unicode code points, not UTF-16 `char` values, and must be positive; otherwise throw `IllegalArgumentException`.\\n\\nReturn every overlapping slice of exactly `sliceLength` code points, scanning from left to right. If an identical slice occurs more than once, include only its first occurrence. Preserve first-occurrence order. If the canonical text is shorter than `sliceLength`, return an empty list.\\n\\nDo not use filesystem access, networking, clocks, randomness, external packages, or frameworks.\",\"reference_code\":\"import java.text.Normalizer;\\nimport java.util.ArrayList;\\nimport java.util.LinkedHashSet;\\nimport java.util.List;\\nimport java.util.Locale;\\nimport java.util.Set;\\n\\npublic final class Solution {\\n    public static List<String> uniqueSlices(String text, int sliceLength) {\\n        if (sliceLength <= 0) {\\n            throw new IllegalArgumentException(\\\"sliceLength must be positive\\\");\\n        }\\n\\n        String normalized = Normalizer.normalize(text, Normalizer.Form.NFC);\\n        StringBuilder compact = new StringBuilder();\\n        normalized.codePoints().forEach(cp -> {\\n            if (!Character.isWhitespace(cp) && !Character.isSpaceChar(cp)) {\\n                compact.appendCodePoint(cp);\\n            }\\n        });\\n        String canonical = Normalizer.normalize(\\n                compact.toString().toLowerCase(Locale.ROOT), Normalizer.Form.NFC);\\n        int count = canonical.codePointCount(0, canonical.length());\\n        Set<String> slices = new LinkedHashSet<String>();\\n\\n        for (int start = 0; start + sliceLength <= count; start++) {\\n            int from = canonical.offsetByCodePoints(0, start);\\n            int to = canonical.offsetByCodePoints(from, sliceLength);\\n            slices.add(canonical.substring(from, to));\\n        }\\n        return new ArrayList<String>(slices);\\n    }\\n}\\n\",\"known_bad_code\":\"import java.text.Normalizer;\\nimport java.util.ArrayList;\\nimport java.util.List;\\nimport java.util.Locale;\\n\\npublic final class Solution {\\n    public static List<String> uniqueSlices(String text, int sliceLength) {\\n        if (sliceLength <= 0) {\\n            throw new IllegalArgumentException(\\\"sliceLength must be positive\\\");\\n        }\\n\\n        String normalized = Normalizer.normalize(text, Normalizer.Form.NFC);\\n        StringBuilder compact = new StringBuilder();\\n        normalized.codePoints().forEach(cp -> {\\n            if (!Character.isWhitespace(cp) && !Character.isSpaceChar(cp)) {\\n                compact.appendCodePoint(cp);\\n            }\\n        });\\n        String canonical = Normalizer.normalize(\\n                compact.toString().toLowerCase(Locale.ROOT), Normalizer.Form.NFC);\\n        int count = canonical.codePointCount(0, canonical.length());\\n        List<String> slices = new ArrayList<String>();\\n\\n        for (int start = 0; start + sliceLength <= count; start++) {\\n            int from = canonical.offsetByCodePoints(0, start);\\n            int to = canonical.offsetByCodePoints(from, sliceLength);\\n            slices.add(canonical.substring(from, to));\\n        }\\n        return slices;\\n    }\\n}\\n\",\"known_bad_label\":\"Repeated canonical slices are appended every time instead of being deduplicated while preserving first-occurrence order.\"},{\"id\":\"cap-v2-string_and_unicode-java-repair-01\",\"problem\":\"Repair the program below. Return one complete `Solution.java` file containing a public final class `Solution` and the exact API `public static List<String> reverseText(List<String> values)`.\\n\\nThe method must reverse each string by Unicode code point, so a supplementary character represented by a surrogate pair remains intact. Return the transformed strings in the same list order. The input list must remain unchanged, and the returned list must be a separate list that does not alias the input.\\n\\nDo not use filesystem access, networking, clocks, randomness, external packages, or frameworks.\\n\\nKnown-bad source:\\n\\n```java\\nimport java.util.ArrayList;\\nimport java.util.List;\\n\\npublic final class Solution {\\n    public static List<String> reverseText(List<String> values) {\\n        List<String> result = new ArrayList<String>(values.size());\\n        for (String value : values) {\\n            StringBuilder reversed = new StringBuilder(value.length())