ace` or `Character.isSpaceChar` is true. Preserve all other code points and preserve list order.\\n\\nThe input list must not be modified. Return a separate list so that subsequently replacing an element in the result cannot alter the input list, and replacing an element in the input cannot alter the result list.\\n\\nDo not use filesystem access, networking, clocks, randomness, external packages, or frameworks.\\n\\nKnown-bad source:\\n\\n```java\\nimport java.util.List;\\n\\npublic final class Solution {\\n    public static List<String> stripUnicodeEnds(List<String> values) {\\n        for (int i = 0; i < values.size(); i++) {\\n            values.set(i, strip(values.get(i)));\\n        }\\n        return values;\\n    }\\n\\n    private static String strip(String value) {\\n        int start = 0;\\n        int end = value.length();\\n        while (start < end) {\\n            int cp = value.codePointAt(start);\\n            if (!isSpace(cp)) {\\n                break;\\n            }\\n            start += Character.charCount(cp);\\n        }\\n        while (end > start) {\\n            int cp = value.codePointBefore(end);\\n            if (!isSpace(cp)) {\\n                break;\\n            }\\n            end -= Character.charCount(cp);\\n        }\\n        return value.substring(start, end);\\n    }\\n\\n    private static boolean isSpace(int codePoint) {\\n        return Character.isWhitespace(codePoint) || Character.isSpaceChar(codePoint);\\n    }\\n}\\n```\",\"reference_code\":\"import java.util.ArrayList;\\nimport java.util.List;\\n\\npublic final class Solution {\\n    public static List<String> stripUnicodeEnds(List<String> values) {\\n        List<String> result = new ArrayList<String>(values.size());\\n        for (String value : values) {\\n            result.add(strip(value));\\n        }\\n        return result;\\n    }\\n\\n    private static String strip(String value) {\\n        int start = 0;\\n        int end = value.length();\\n        while (start < end) {\\n            int cp = value.codePointAt(start);\\n            if (!isSpace(cp)) {\\n                break;\\n            }\\n            start += Character.charCount(cp);\\n        }\\n        while (end > start) {\\n            int cp = value.codePointBefore(end);\\n            if (!isSpace(cp)) {\\n                break;\\n            }\\n            end -= Character.charCount(cp);\\n        }\\n        return value.substring(start, end);\\n    }\\n\\n    private static boolean isSpace(int codePoint) {\\n        return Character.isWhitespace(codePoint) || Character.isSpaceChar(codePoint);\\n    }\\n}\\n\",\"known_bad_code\":\"import java.util.List;\\n\\npublic final class Solution {\\n    public static List<String> stripUnicodeEnds(List<String> values) {\\n        for (int i = 0; i < values.size(); i++) {\\n            values.set(i, strip(values.get(i)));\\n        }\\n        return values;\\n    }\\n\\n    private static String strip(String value) {\\n        int start = 0;\\n        int end = value.length();\\n        while (start < end) {\\n            int cp = value.codePointAt(start);\\n            if (!isSpace(cp)) {\\n                break;\\n            }\\n            start += Character.charCount(cp);\\n        }\\n        while (end > start) {\\n            int cp = value.codePointBefore(end);\\n            if (!isSpace(cp)) {\\n                break;\\n            }\\n            end -= Character.charCount(cp);\\n        }\\n        return value.substring(start, end);\\n    }\\n\\n    private static boolean isSpace(int codePoint) {\\n        return Character.isWhitespace(codePoint) || Character.isSpaceChar(codePoint);\\n    }\\n}\\n\",\"known_bad_label\":\"The method transforms and returns the input list itself, violating the required input immutability and list independence.\"}]}"}}
