```java
import java.util.ArrayDeque;
import java.util.ArrayList;
import java.util.Deque;
import java.util.HashMap;
import java.util.List;
import java.util.Map;

public final class Solution {
    private static final class State {
        int value;
        boolean active = true;
        final Deque<Integer> previousValues = new ArrayDeque<Integer>();
    }

    public static List<String> execute(List<String> commands) {
        Map<String, State> states = new HashMap<String, State>();
        List<String> output = new ArrayList<String>();
        State shared = new State();

        for (String command : commands) {
            String[] parts = command.split(" ");
            String operation = parts[0];
            String id = parts[1];

            if (operation.equals("OPEN")) {
                if (states.containsKey(id)) {
                    throw new IllegalStateException("workflow already exists: " + id);
                }
                states.put(id, shared);
                output.add(id + "=OPEN");
                continue;
            }

            State state = states.get(id);
            if (state == null) {
                throw new IllegalStateException("unknown workflow: " + id);
            }
            if (!state.active) {
                throw new IllegalStateException("workflow is committed: " + id);
            }

            if (operation.equals("ADD")) {
                int delta = Integer.parseInt(parts[2]);
                state.previousValues.push(state.value);
                state.value += delta;
                output.add(id + "=" + state.value);
            } else if (operation.equals("ROLLBACK")) {
                if (state.previousValues.isEmpty()) {
                    throw new IllegalStateException("nothing to roll back: " + id);
                }
                state.value = state.previousValues.pop();
                output.add(id + "=" + state.value);
            } else if (operation.equals("COMMIT")) {
                state.active = false;
                state.previousValues.clear();
                output.add(id + "=COMMITTED:" + state.value);
            }
        }
        return output;
    }
}
