ngAction() {\\n            public void run() {\\n                Solution.execute(Arrays.asList(\\\"ADD missing 1\\\"));\\n            }\\n        });\\n        expectIllegalState(new ThrowingAction() {\\n            public void run() {\\n                Solution.execute(Arrays.asList(\\\"OPEN empty\\\", \\\"ROLLBACK empty\\\"));\\n            }\\n        });\\n        expectIllegalState(new ThrowingAction() {\\n            public void run() {\\n                Solution.execute(Arrays.asList(\\\"OPEN done\\\", \\\"COMMIT done\\\", \\\"ADD done 1\\\"));\\n            }\\n        });\\n        expectIllegalState(new ThrowingAction() {\\n            public void run() {\\n                Solution.execute(Arrays.asList(\\\"OPEN done\\\", \\\"COMMIT done\\\", \\\"ROLLBACK done\\\"));\\n            }\\n        });\\n        expectIllegalState(new ThrowingAction() {\\n            public void run() {\\n                Solution.execute(Arrays.asList(\\\"OPEN done\\\", \\\"COMMIT done\\\", \\\"COMMIT done\\\"));\\n            }\\n        });\\n    }\\n\\n    private interface ThrowingAction {\\n        void run();\\n    }\\n\\n    private static void expectIllegalState(ThrowingAction action) {\\n        try {\\n            action.run();\\n            throw new AssertionError(\\\"Expected IllegalStateException\\\");\\n        } catch (IllegalStateException expected) {\\n            // Expected.\\n        }\\n    }\\n\\n    private static void assertListEquals(List<String> expected, List<String> actual) {\\n        if (!expected.equals(actual)) {\\n            throw new AssertionError(\\\"Expected \\\" + expected + \\\" but got \\\" + actual);\\n        }\\n    }\\n}\\n\"},{\"id\":\"cap-v2-string_and_unicode-java-generation-01\",\"test_code\":\"import java.util.ArrayList;\\nimport java.util.Arrays;\\nimport java.util.Collections;\\nimport java.util.List;\\nimport java.util.Locale;\\n\\npublic class SolutionTest {\\n    public static void main(String[] args) {\\n        Locale originalLocale = Locale.getDefault();\\n        try {\\n            Locale.setDefault(new Locale(\\\"tr\\\", \\\"TR\\\"));\\n            testNormalizationTrimmingDeduplicationAndOrder();\\n            testCodePointBoundary();\\n            testEmptyRegistrationSet();\\n            testInvalidNamesAndQuery();\\n        } finally {\\n            Locale.setDefault(originalLocale);\\n        }\\n    }\\n\\n    private static void testNormalizationTrimmingDeduplicationAndOrder() {\\n        List<String> proposed = new ArrayList<String>(Arrays.asList(\\n                \\\"\\\\u00A0Alpha\\\\u2003\\\",\\n                \\\"Cafe\\\\u0301\\\",\\n                \\\"CAFÉ\\\",\\n                \\\"beta\\\",\\n                \\\"GAMMA\\\",\\n                \\\"gamma\\\"));\\n        List<String> snapshot = new ArrayList<String>(proposed);\\n\\n        assertListEquals(Arrays.asList(\\\"Alpha\\\", \\\"Café\\\", \\\"GAMMA\\\"),\\n                Solution.registerAndFind(proposed, \\\"\\\\u2003A\\\\u00A0\\\"));\\n        assertListEquals(Collections.singletonList(\\\"Café\\\"),\\n                Solution.registerAndFind(proposed, \\\"FE\\\\u0301\\\"));\\n        assertListEquals(Collections.singletonList(\\\"Alpha\\\"),\\n                Solution.registerAndFind(proposed, \\\"ALP\\\"));\\n        assertListEquals(Collections.<String>emptyList(),\\n                Solution.registerAndFind(proposed, \\\"zzz\\\"));\\n        assertListEquals(snapshot, proposed);\\n    }\\n\\n    private static void testCodePointBoundary() {\\n        String emoji = \\\"\\\\uD83D\\\\uDE00\\\";\\n        StringBuilder twenty = new StringBuilder();\\n        for (int i = 0; i < 20; i++) {\\n            twenty.append(emoji);\\n        }\\n        assertListEquals(Collections.singletonList(twenty.toString()),\\n                Solution.registerAndFind(Collections.singletonList(twenty.toString()), emoji));\\n\\n        final StringBuilder twentyOne = new StringBuilder(twenty);\\n        twentyOne.append(emoji);\\n        expectIllegalArgument(new ThrowingAction() {\\n            public void run() {\\n                Solution.registerAndFind(Collections.singletonList(twentyOne.toString()), \\\"x\\\");\\n            }\\n        });\\n    }\\n\\n    private static void testEmptyRegistrationSet() {\\n        assertListEquals(Collections.<String>emptyList(),\\n                Solution.registerAndFind(Collections.<String>emptyList(), \\\"valid\\\"));\\n    }\\n\\n    private static void testInvalidNamesAndQuery() {\\n        expectIllegalArgument(new ThrowingAction() {\\n            public void run() {\\n                Solution.registerAndFind(Collections.singletonList(\\\"\\\\t\\\\u00A0\\\\u2003\\\"), \\\"x\\\");\\n            }\\n        });\\n        expectIllegalArgument(new ThrowingAction() {\\n            public void run() {\\n                Solution.registerAndFind(Collections.singletonList(\\\"abcdefghijklmnopqrstu\\\"), \\\"x\\\");\\n            }\\n        });\\n        expectIllegalArgument(new ThrowingAction() {\\n            public void run() {\\n                Solution.registerAndFind(Collections.singletonList(\\\"valid\\\"), \\\"\\\\n\\\\u00A0\\\\u2003\\\");\\n            }\\n        });\\n    }\\n\\n    private interface ThrowingAction {\\n        void run();\\n    }\\n\\n    private static void expectIllegalArgument(ThrowingAction action) {\\n        try {\\n            action.run();\\n            throw new AssertionError(\\\"Expected IllegalArgumentException\\\");\\n        } catch (IllegalArgumentException expected) {\\n            // Expected.\\n        }\\n    }\\n\\n    private static void assertListEquals(List<String> expected, List<String> actual) {\\n        if (!expected.equals(actual)) {\\n            throw new AssertionError(\\\"Expected \\\" + expected + \\\" but got \\\" + actual);\\n        }\\n    }\\n}\\n\"},{\"id\":\"cap-v2-string_and_unicode-java-generation-02\",\"test_code\":\"import java.util.Arrays;\\nimport java.util.Collections;\\nimport java.util.List;\\nimport java.util.Locale;\\n\\npublic class SolutionTest {\\n    public static void main(String[] args) {\\n        Locale originalLocale = Locale.getDefault();\\n        try {\\n            Locale.setDefault(new Locale(\\\"tr\\\", \\\"TR\\\"));\\n            assertListEquals(Arrays.asList(\\\"ab\\\", \\\"ba\\\"),\\n                    Solution.uniqueSlices(\\\" A\\\\u00A0B\\\\tA\\\\u2003b \\\", 2));\\n\\n            String emoji = \\\"\\\\uD83D\\\\uDE00\\\";\\n            assertListEquals(Arrays.asList(emoji + \\\"a\\\", \\\"a\\\" + emoji),\\n                    Solution.uniqueSlices(emoji + \\\"A\\\" + emoji + \\\"a\\\", 2));\\n\\n            assertListEquals(Arrays.asList(\\\"é\\\", \\\"x\\\"),\\n                    Solution.uniqueSlices(\\\" E\\\\u0301  X \\\", 1));\\n\\n            assertListEquals(Collections.singletonList(\\\"i\\\"),\\n                    Solution.uniqueSlices(\\\"I I\\\", 1));\\n\\n            assertListEquals(Collections.<String>emptyList(),\\n                    Solution.uniqueSlices(\\\"\\\", 1));\\n            assertListEquals(Collections.<String>emptyList(),\\n                    Solution.uniqueSlices(\\\"a\\\", 2));\\n            assertListEquals(Collections.singletonList(\\\"abc\\\"),\\n                    Solution.uniqueSlices(\\\"ABC\\\", 3));\\n\\n            expectIllegalArgument(new ThrowingAction() {\\n                public void run() {\\n                    Solution.uniqueSlices(\\\"abc\\\", 0);\\n                }\\n            });\\n            expectIllegalArgument(new ThrowingAction() {\\n                public void run() {\\n                    Solution.uniqueSlices(\\\"abc\\\", -1);\\n                }\\n            });\\n        } finally {\\n            Locale.setDefault(originalLocale);\\n        }\\n    }\\n\\n    private interface ThrowingAction {\\n        void run();\\n    }\\n\\n    private static void expectIllegalArgument(ThrowingAction action) {\\n        try {\\n            action.r