mptyInput);\\n        assertListEquals(Collections.<String>emptyList(), emptyResult);\\n        if (emptyInput == emptyResult) {\\n            throw new AssertionError(\\\"Empty returned list aliases input list\\\");\\n        }\\n    }\\n\\n    private static void assertEquals(String expected, String actual) {\\n        if (!expected.equals(actual)) {\\n            throw new AssertionError(\\\"Expected \\\" + expected + \\\" but got \\\" + actual);\\n        }\\n    }\\n\\n    private static void assertListEquals(List<String> expected, List<String> actual) {\\n        if (!expected.equals(actual)) {\\n            throw new AssertionError(\\\"Expected \\\" + expected + \\\" but got \\\" + actual);\\n        }\\n    }\\n}\\n\"},{\"id\":\"cap-v2-string_and_unicode-java-repair-02\",\"test_code\":\"import java.util.ArrayList;\\nimport java.util.Arrays;\\nimport java.util.Collections;\\nimport java.util.List;\\n\\npublic class SolutionTest {\\n    public static void main(String[] args) {\\n        String emoji = \\\"\\\\uD83D\\\\uDE00\\\";\\n        List<String> input = new ArrayList<String>(Arrays.asList(\\n                \\\"  alpha  \\\",\\n                \\\"\\\\u00A0\\\\u2003beta\\\\t\\\\n\\\",\\n                \\\"\\\\u2003\\\",\\n                \\\"\\\",\\n                \\\"gamma\\\\u00A0delta\\\",\\n                \\\"\\\\u00A0\\\" + emoji + \\\"\\\\u2003\\\",\\n                \\\"plain\\\"));\\n        List<String> snapshot = new ArrayList<String>(input);\\n\\n        List<String> result = Solution.stripUnicodeEnds(input);\\n        assertListEquals(Arrays.asList(\\n                \\\"alpha\\\",\\n                \\\"beta\\\",\\n                \\\"\\\",\\n                \\\"\\\",\\n                \\\"gamma\\\\u00A0delta\\\",\\n                emoji,\\n                \\\"plain\\\"), result);\\n        assertListEquals(snapshot, input);\\n        if (result == input) {\\n            throw new AssertionError(\\\"Returned list aliases input list\\\");\\n        }\\n\\n        result.set(0, \\\"changed-result\\\");\\n        assertEquals(\\\"  alpha  \\\", input.get(0));\\n\\n        input.set(1, \\\"changed-input\\\");\\n        assertEquals(\\\"beta\\\", result.get(1));\\n\\n        List<String> emptyInput = new ArrayList<String>();\\n        List<String> emptyResult = Solution.stripUnicodeEnds(emptyInput);\\n        assertListEquals(Collections.<String>emptyList(), emptyResult);\\n        if (emptyInput == emptyResult) {\\n            throw new AssertionError(\\\"Empty returned list aliases input list\\\");\\n        }\\n    }\\n\\n    private static void assertEquals(String expected, String actual) {\\n        if (!expected.equals(actual)) {\\n            throw new AssertionError(\\\"Expected \\\" + expected + \\\" but got \\\" + actual);\\n        }\\n    }\\n\\n    private static void assertListEquals(List<String> expected, List<String> actual) {\\n        if (!expected.equals(actual)) {\\n            throw new AssertionError(\\\"Expected \\\" + expected + \\\" but got \\\" + actual);\\n        }\\n    }\\n}\\n\"}]}"}}
